<script>
import { defineComponent, onMounted, ref, watch } from "vue";
import { userStore } from "stores/index";
import { useUI } from "stores/ui";
import { useRoute } from "vue-router";
// import EssentialLink from "components/EssentialLink.vue";

import {
  RiWalletLine,
  RiCoinsLine,
  RiHomeLine,
  RiUserSmileLine,
  RiCustomerService2Fill,
  RiArrowDropLeftLine
} from "vue-remix-icons";

export default defineComponent({
  name: "MainLayout",

  components: {
    RiWalletLine,
    RiCoinsLine,
    RiHomeLine,
    RiUserSmileLine,
    RiCustomerService2Fill,
    RiArrowDropLeftLine
  },

  setup() {
    const route = useRoute();
    const store = userStore();
    const ui = useUI();
    const scrollPageRef = ref(null);
    ui.$onAction(({ name, args }) => {
      switch (name) {
        case "setScrollPosition":
          scrollPageRef.value.setScrollPosition(args[0], args[1], args[2]);
      }
    });
    const logout = () => {
      store.memberLogout().then(() => {
        location.reload();
      });
    };
    watch(
      () => route.path,
      async () => {
        checkRoute();
      }
    );
    const checkRoute = () => {
      if (route) {
        hasPage.value = false;
        pageName.value = "";
        if (route.path === "/slot") {
          hasPage.value = true;
          pageName.value = "สล็อต";
        } else if (route.path === "/live-casino") {
          hasPage.value = true;
          pageName.value = "ไลฟ์คาซิโน";
        } else if (route.path === "/poker") {
          hasPage.value = true;
          pageName.value = "Poker";
        } else if (route.path === "/e-sport") {
          hasPage.value = true;
          pageName.value = "Esports";
        } else if (route.path === "/sport") {
          hasPage.value = true;
          pageName.value = "กีฬา";
        } else if (route.path === "/aviator") {
          hasPage.value = true;
          pageName.value = "ตกปลา";
        }
      }
    };
    const pageName = ref("");
    const hasPage = ref(false);
    const leftDrawerOpen = ref(false);
    onMounted(() => {
      checkRoute();
    });
    return {
      tab: ref("home"),
      leftDrawerOpen,
      toggleLeftDrawer() {
        leftDrawerOpen.value = !leftDrawerOpen.value;
      },
      logout,
      store,
      scrollPageRef,
      pageName,
      hasPage
    };
  }
});
</script>

